-- supabase/sql/exam_question_bank_upsc_cse_set1.sql
--
-- First curated question-bank batch for 'UPSC CSE (IAS)' (see exam_patterns_upsc_cse.sql for the
-- exam's structure). Same exam_question_bank table/schema as the other sets -- no migration
-- needed. Models Prelims only (both GS Paper I and CSAT Paper II) -- Mains/Interview are not
-- MCQ-based and don't fit this schema.
--
-- Like NEET/BITSAT/MHT-CET/WBJEE/VITEEE, every row here is format='mcq' with a single
-- isCorrect:true option (100% single-best-response, matching the real exam). The "Current Affairs"
-- chapter deliberately sticks to durable, evergreen institutional facts (headquarters, founding
-- years, regional groupings) rather than time-sensitive news, since a static question bank would
-- otherwise go stale. 16 chapters (10 GS Paper I, 6 CSAT Paper II) each get 4 questions.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_upsc_cse.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

