 '[{"text":"Buddhist paintings and sculptures","isCorrect":true},{"text":"Jain temple architecture only","isCorrect":false},{"text":"Islamic calligraphy","isCorrect":false},{"text":"Sikh gurdwaras","isCorrect":false}]'::jsonb,
 null, 'The Ajanta Caves in Maharashtra are a series of Buddhist rock-cut monuments famous for their exquisite paintings and sculptures dating back over two millennia.'),
('UPSC CSE (IAS)', 'General Studies Paper I', 'Ancient Indian History', 'easy', 'mcq',
 'Which Veda is considered the oldest and consists primarily of hymns?',
 '[{"text":"Yajurveda","isCorrect":false},{"text":"Samaveda","isCorrect":false},{"text":"Rigveda","isCorrect":true},{"text":"Atharvaveda","isCorrect":false}]'::jsonb,
