 '[{"text":"Frequent elections alone","isCorrect":false},{"text":"An informed and accountable-holding electorate","isCorrect":true},{"text":"A large voting population","isCorrect":false},{"text":"The absence of political parties","isCorrect":false}]'::jsonb,
