 '[{"text":"All doctors are researchers.","isCorrect":true},{"text":"All researchers are doctors.","isCorrect":false},{"text":"No doctors are researchers.","isCorrect":false},{"text":"Some scientists are not researchers.","isCorrect":false}]'::jsonb,
 null, 'By transitive syllogism, since all doctors are scientists and all scientists are researchers, it necessarily follows that all doctors are researchers.'),
('UPSC CSE (IAS)', 'CSAT (General Studies Paper II)', 'Logical Reasoning and Analytical Ability', 'easy', 'mcq',
